def rows_to_dict(rows):
    """
    Convert a list of rows (each row is a tuple or list) into a dictionary where
    each row becomes a key, and the value is a dictionary of column names to values.

    Args:
        rows: List of tuples/lists, where each tuple/list represents a row.
              Each row should have the same number of columns.

    Returns:
        dict: A dictionary where keys are row indices (0, 1, 2, ...) and values
              are dictionaries mapping column names to values in that row.

    Example:
        rows = [
            ('Alice', 25, 'Engineer'),
            ('Bob', 30, 'Manager')
        ]
        rows_to_dict(rows) returns:
        {
            0: {'name': 'Alice', 'age': 25, 'job': 'Engineer'},
            1: {'name': 'Bob', 'age': 30, 'job': 'Manager'}
        }
    """
    if not rows:
        return {}

    # Assume the first row contains the column names
    headers = rows[0]

    # Create a dictionary for each row
    result = {}
    for i, row in enumerate(rows[1:]):
        # Create a dictionary mapping column names to values
        row_dict = {}
        for j, value in enumerate(row):
            row_dict[headers[j]] = value
        result[i] = row_dict

    return result

